mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM share
    WHERE task_id = #{taskId}
      AND receiver_id = #{userId}
      AND (due_time IS NULL OR due_time > NOW())
) AS exists_flag;

SELECT EXISTS (
    SELECT 1
    FROM share
    WHERE task_id = #{taskId}
      AND company_id = #{userCompanyId}
      AND (due_time IS NULL OR due_time > NOW())
) AS exists_flag;

SELECT COUNT(*) > 0
FROM scMoAnnoTask t
JOIN scMoAnnoUser u ON t.uploader_id = u.user_id
WHERE t.task_id = #{taskId}
  AND u.psw = SHA2(#{password}, 256);
